// RegisterAccessServiceHandler registers svc as the nopacs.v1.AccessService implementation on
// server.
func RegisterAccessServiceHandler(server *connect.Server, svc AccessServiceHandler) {
	adapter := accessServiceHandler{svc: svc}
	server.Register(
		connect.Method{Spec: accessServiceCreateKeySpec(), Handler: adapter.createKey},
		connect.Method{Spec: accessServiceGetKeySpec(), Handler: adapter.getKey},
		connect.Method{Spec: accessServiceListKeysSpec(), Handler: adapter.listKeys},
		connect.Method{Spec: accessServiceRevokeKeySpec(), Handler: adapter.revokeKey},
		connect.Method{Spec: accessServiceSetGrantSpec(), Handler: adapter.setGrant},
		connect.Method{Spec: accessServiceListGrantsSpec(), Handler: adapter.listGrants},
		connect.Method{Spec: accessServiceRemoveGrantSpec(), Handler: adapter.removeGrant},
		connect.Method{Spec: accessServiceWhoAmISpec(), Handler: adapter.whoAmI},
		connect.Method{Spec: accessServiceRotateKeySpec(), Handler: adapter.rotateKey},
		connect.Method{Spec: accessServiceSetKeyRulesSpec(), Handler: adapter.setKeyRules},
		connect.Method{Spec: accessServiceReinstateKeysSpec(), Handler: adapter.reinstateKeys},
	)
}

